#!/usr/bin/env node
/**
 * Copies the table of `docs/platform-matrix.md` (generated by `tests/platform-matrix/run.mjs`) into
 * the docs site page `docs/sdk/site/platforms/matrix.mdx`, between two marker comments, so the
 * page cannot drift from the matrix. Pure text: it runs under plain node in `pnpm docs:check`.
 */
import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import process from 'node:process';
import { fileURLToPath, pathToFileURL } from 'node:url';

export const PLATFORM_MATRIX_SOURCE = 'docs/platform-matrix.md';
export const PLATFORM_MATRIX_PAGE = 'docs/sdk/site/platforms/matrix.mdx';

const START = '{/* platform-matrix:start */}';
const END = '{/* platform-matrix:end */}';
const FIX = 'run `node scripts/docs/sync-platform-matrix.mjs --write`';

/**
 * @param {string} source
 * @returns {string} The `|`-lines of `source`, in order.
 */
export function matrixTable(source) {
  const rows = source.split('\n').filter((line) => line.startsWith('|'));
  if (rows.length === 0) throw new Error(`${PLATFORM_MATRIX_SOURCE} has no table`);
  return rows.join('\n');
}

/**
 * @param {string} page
 * @param {string} table
 * @returns {string} `page` with the text between the markers replaced by `table`.
 */
export function withMatrixRegion(page, table) {
  const start = page.indexOf(START);
  if (start === -1) throw new Error(`${PLATFORM_MATRIX_PAGE} has no ${START} marker`);
  const end = page.indexOf(END, start);
  if (end === -1) throw new Error(`${PLATFORM_MATRIX_PAGE} has no ${END} marker after ${START}`);
  return `${page.slice(0, start + START.length)}\n\n${table}\n\n${page.slice(end)}`;
}

/** @param {readonly string[]} argv @param {string} repoRoot */
async function main(argv, repoRoot) {
  const write = argv.includes('--write');
  if (!write && !argv.includes('--check')) {
    process.stderr.write('usage: sync-platform-matrix.mjs --write | --check\n');
    return 2;
  }
  const pageFile = path.join(repoRoot, PLATFORM_MATRIX_PAGE);
  const table = matrixTable(await readFile(path.join(repoRoot, PLATFORM_MATRIX_SOURCE), 'utf8'));
  const page = await readFile(pageFile, 'utf8');
  const synced = withMatrixRegion(page, table);
  if (write) {
    await writeFile(pageFile, synced, 'utf8');
    process.stdout.write(`wrote ${PLATFORM_MATRIX_PAGE}\n`);
    return 0;
  }
  if (synced === page) {
    process.stdout.write(`${PLATFORM_MATRIX_PAGE} is current with ${PLATFORM_MATRIX_SOURCE}\n`);
    return 0;
  }
  process.stderr.write(`stale: ${PLATFORM_MATRIX_PAGE} — ${FIX}\n`);
  return 1;
}

const invokedPath = process.argv[1];
if (
  invokedPath !== undefined &&
  pathToFileURL(path.resolve(invokedPath)).href === import.meta.url
) {
  const repoRoot = path.resolve(fileURLToPath(import.meta.url), '../../..');
  process.exitCode = await main(process.argv.slice(2), repoRoot);
}
